const ALREADY_LIST = ["nix-flakes.md (NIX-FLK: systems iteration, nixpkgs instantiation, outputs contract, self-source reads, overlays, apps/templates, devShells)", "nix-gates.md (NIX-GATE: nixfmt/deadnix/statix/nixf gates, nix flake check semantics and limits, CI installer and cache, implementation matrix, consumer Nix floor)", "nix-generated-flakes.md (NIX-GEN: ocx index to flake data model, OCI blob fetch, attribute shape, libc/platform mapping, updater)"]
const EXISTING = new Set(["flakes", "gates", "generated-flakes"])

const ROOT = '/home/mherwig/dev/grimoire-lore/.agents/worktrees/nix'
const RESEARCH = ROOT + '/.agents/research'
const FRAME = RESEARCH + '/nix-frame.md'
const MAP = RESEARCH + '/nix-topic-map.md'
const EX = '/home/mherwig/.cache/research-lang/exemplars/nix'
const EXLOG = '/home/mherwig/.cache/research-lang/exemplars/nix-fetch.log'
const RUN = '/home/mherwig/.cache/research-lang/nix-tools/run.sh'
const FIX = '/home/mherwig/.cache/research-lang/nix-tools/fixtures'
const ALREADY = ALREADY_LIST.map(s => '- ' + s).join('\n') || '- (nothing consolidated yet)'

const CONTEXT = `PROJECT CONTEXT (context for you, not content to reproduce):
- This is wave ${WAVE} of the research program that makes an AI-agent fleet expert in Nix: the language, nixpkgs packaging, and above all authoring, maintaining, versioning and publishing flakes at a high quality bar with great consumer UX, plus generating a flake from the ocx package index. Its output becomes AI-agent configuration (a glob-scoped rule with a support directory, one to three skills, a bundle) used by coding agents without a human in the loop, published through the lore catalog at ${ROOT} (a git worktree — treat it as the repository root; never cd to /home/mherwig/dev/grimoire-lore), plus a design handoff for ocx.
- Read the frame first (${FRAME}, including its Corrections), then the topic map (${MAP}): its "Conflicts resolved", "Artifact set decision" and the row(s) your brief cites. The map's decisions bind you; your job is depth, not re-deciding the artifact shape.
- THE FLEET HAS NO NIX CODE. Evidence comes from the exemplar corpus of 38 repositories under ${EX}/<owner>__<repo> (blob-less sparse clones: *.nix, flake.lock, .github/, nix/ and root files only; SHAs in ${EXLOG}) and the three audits under ${RESEARCH}/nix-audit/ which already measured them and ran the real tools — cite the audits, re-measure only what your brief needs. Cite <repo>@<sha12>:<path>:<line>. Evaluate third-party flakes by remote ref 'github:owner/repo/<full-sha>' (the clones are sparse) and always with --no-write-lock-file.
- A REAL TOOLCHAIN is available, rootless: '${RUN} <cmd> [args]' (for pipelines '${RUN} bash -c "..."') runs Nix 2.35.2 with nixfmt 1.5.0, statix, deadnix, nixd, nil, flake-checker, nix-update, nurl, nix-prefetch-git, nix-tree, nix-diff, treefmt, skopeo, git, jq, curl on PATH; sandboxed builds work; github.com access token configured. Other Nix versions and Lix are reachable as '${RUN} nix shell nixpkgs#nixVersions.nix_2_24 --command ...' or 'nixpkgs#lix'. STORE DISCIPLINE: use ONLY '${RUN}'; never invoke nix-portable directly, never unset or change NP_LOCATION, never create a second store, never run 'nix store gc', 'nix-collect-garbage' or 'nix store optimise'. Since 2026-09-27 run.sh enters the shared on-disk store through bwrap directly with SQLite WAL on (wave 2's contention came from nix-portable's launcher forcing WAL off and racing on start-up); ten parallel builds were measured to succeed. If a command still makes no progress for 5 minutes, record it as blocked with the command, and move on. Build planted fixtures — tiny throwaway flakes — under ${FIX}/<your-slug>/ (never /tmp, never inside an exemplar clone); run 'git init -q && git add -A' in each fixture because flakes only see tracked files. RUN every verification you propose against a planted violation AND a compliant twin: a verification is only admissible if you watched it go red on the violation and stay green on the twin. Record the exact command, the exit code and the relevant output lines in the artifact. Never pass --impure, --accept-flake-config or --option sandbox false to third-party code; never build large packages (compilers, editors, NixOS systems) — evaluation and small fixture builds only; bound runs with 'timeout 900'.
- Consumers the artifacts must serve: (a) the fleet's future flakes — Rust CLIs /home/mherwig/dev/ocx and /home/mherwig/dev/grimoire, the Python SDK /home/mherwig/dev/ocx-sdk-python, GitHub Actions — published at a high bar; (b) a flake generated from the ocx package index (see nix-audit/ocx-index-and-fleet.md); (c) the general Nix adopter.
- Sibling lore sets own Rust/Go/Python/TypeScript/JVM packaging, Bazel, and docs topics; a Nix dive covers the Nix side of the seam and cites them rather than restating them.
- Use read-only tools on every repository; the only files you may create or modify are your own OUTPUT FILE and your fixture directory. Date everything ${DATE}; version-tag every Nix-, nixpkgs- or tool-version-specific claim and say which implementation (CppNix / Lix / Determinate Nix) it describes when they differ.

ALREADY COVERED (do not re-tread; cite these consolidations' rule IDs instead):
${ALREADY}
`

const DIVE_CONTRACT = (path) => `OUTPUT FILE: ${path}
Write it with the Write tool; create parent directories as needed.

Structure, in this order:
1. YAML frontmatter: title, topic, agent (your label), model: sonnet, date_researched: ${DATE}, sources_count, fixtures (the fixture directory you used), scope (2-3 lines on what is and is not covered).
2. A table of contents.
3. "## Summary" — 10-20 bullet lines, each a standalone actionable claim.
4. "## Findings" — numbered subsections. EVERY non-obvious claim carries an inline citation as a markdown link to the exact URL read, or a repo@sha12:path:line into the exemplar corpus. Correct and incorrect Nix side by side wherever a rule is easier shown than told. Exact attribute names, builtins, lib functions, lint codes, flags, settings, command lines and numeric thresholds, with the Nix / nixpkgs / tool version they apply to.
5. "## Normative guidance candidates" — numbered, crisp, checkable imperative rules distilled from the findings, each with: the rule, a one-line rationale, how a reviewer VERIFIES it (a nix command or 'nix eval' expression, a statix/deadnix/nixfmt/flake-checker invocation, a jq query over flake.lock, a grep with an explicit directory operand, or a named reading heuristic), and whether that verification was RUN against a planted violation (yes, with the fixture path / no, reading heuristic only). This is the section that matters most — make it dense and specific.
6. "## Verification runs" — for every runnable verification: fixture path, command, exit code on the violation, exit code on the compliant twin, the relevant output lines. A verification that did not go red is reported as such, with why.
7. "## Exemplar evidence" — which exemplars satisfy, violate or contradict each candidate, with repo@sha12:path:line (from the audits or your own re-measurement).
8. "## AI-agent angle" — what an LLM characteristically gets WRONG here (dated idioms such as flake-utils boilerplate, 'import nixpkgs' per system, with pkgs, rec, sha256 attributes, cargoSha256, stdenv.lib, pkgs.system, nixfmt-rfc-style, channels and nix-env; hallucinated attributes, builtins or flags; patterns that evaluate but are wrong) and the smallest mechanical check that catches each mistake.
9. "## Contested / evolving" — where practice genuinely disagrees or recently changed, and which way it is trending, as of when.
10. "## Sources" — table: URL | what it is | date/era | why worth reading. Minimum 12 distinct sources, at least 6 primary (the Nix / Nixpkgs / NixOS manuals, nix.dev, RFCs, release notes, the tool's own repository or docs, source code).

Hard requirements:
- Call ToolSearch with query "select:WebSearch,WebFetch" FIRST to load the web tools, then research. For GitHub-hosted markdown or source prefer 'curl -sL https://raw.githubusercontent.com/...' through Bash so you read the whole file; the manuals on nix.dev and nixos.org can be fetched with curl too.
- Actually FETCH the primary sources; never write from search snippets.
- Reflect current practice as of ${DATE} (Nix 2.35 / nixpkgs 26.11 era); flag historical-only guidance with the version it stopped applying.
- No "it depends" without saying what it depends on.
- Verification commands you propose must follow this shape (a checker enforces it later): grep/rg always with an explicit directory operand ('.' at minimum) and -r where recursive; one -e per alternative instead of a pipe character inside a pattern; quote every --include glob (write --include='*.nix', never --include=*.nix); never an unquoted '**'; no '$(...)' command substitution; no angle-bracket placeholders inside a search pattern; pipe into 'xargs -r'; a jq program goes in single quotes. Write the check so its OUTPUT is the violation (empty output = pass), and say so.
- Do not modify any file other than your output file and your fixture directory.`

const DIVE_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['path', 'sources_count', 'verifications_run', 'top_rules', 'surprises'],
  properties: {
    path: { type: 'string' },
    sources_count: { type: 'number' },
    verifications_run: { type: 'number', description: 'how many verifications were watched going red on a planted fixture' },
    top_rules: { type: 'array', items: { type: 'string' }, maxItems: 10 },
    surprises: { type: 'array', items: { type: 'string' }, maxItems: 6, description: 'findings the brief did not anticipate and that deserve their own round' },
  },
}

const CONSOLIDATE_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['path', 'rule_ids', 'conflicts_resolved', 'needs_another_round', 'must_count'],
  properties: {
    path: { type: 'string' },
    rule_ids: { type: 'array', items: { type: 'string' }, description: 'ID — imperative, one per rule' },
    conflicts_resolved: { type: 'array', items: { type: 'string' } },
    needs_another_round: { type: 'array', items: { type: 'string' }, description: 'subarea + the question, one per line' },
    must_count: { type: 'number' },
  },
}

function dive(item) {
  const path = RESEARCH + '/nix-' + item.group + '/' + item.slug + '.md'
  return agent(
    `Model rationale: sonnet — online research, source digestion and fixture runs; volume work whose cost is in pages read and commands run, not in judgment.

${CONTEXT}

YOUR SUBAREA: ${item.label} (group: ${item.group_label}; rule family: ${item.id_family}; fixture dir: ${FIX}/${item.slug}/)

RESEARCH BRIEF (from the topic map; follow it exactly):
${item.brief}

${DIVE_CONTRACT(path)}

Return ONLY the structured receipt: the output path, source count, how many verifications you watched go red, your 8 strongest normative rules as one-liners, and up to 6 surprises.`,
    { label: 'dive:' + item.group + '/' + item.slug, phase: 'Dive', model: 'sonnet', effort: 'high', schema: DIVE_SCHEMA },
  )
}

function consolidate(group, items) {
  const path = RESEARCH + '/nix-' + group + '.md'
  const dir = RESEARCH + '/nix-' + group + '/'
  const families = [...new Set(items.map(i => i.id_family))]
  const family = families.join(' + ')
  const label = items[0].group_label
  const revise = EXISTING.has(group)
  const task = revise
    ? `You are REVISING an existing consolidated artifact to fold in a follow-up round it itself commissioned.

Read ${path} IN FULL, then every file in ${dir} in full — including the new artifact(s) this round produced: ${items.map(i => i.slug + '.md').join(', ')}.

Rewrite ${path} in place, preserving its structure:
- ID STABILITY IS A HARD CONTRACT. Every existing rule ID keeps its number and its meaning. Do not renumber, do not reorder into different IDs, do not reuse a retired number.
- New rules get NEW IDs continuing the sequence.
- If the follow-up CONTRADICTS an existing rule, change that rule's text in place and record the change — never leave both standing. A rule that overclaims a guarantee the new research shows does not exist is the most dangerous kind; fix it explicitly.
- A verification the new round watched FAIL to go red must be replaced or the rule demoted to a reading heuristic; record which.
- Update the Verdict for whatever the follow-up settled, and REMOVE from Open questions whatever it answered. Where the research established a GAP rather than an answer, move it into the Verdict as a documented gap.
- Add or extend a "## Revision log": one line per change — what, which IDs, why.
- Update the frontmatter's consolidates list and add a revised: ${DATE} key.`
    : `You are consolidating a topic into the single authoritative artifact a later author works from.

Read EVERY file in ${dir} (list it first; read each in full), plus the three audits under ${RESEARCH}/nix-audit/ (at least the sections relevant to this group) and the topic map's rows for this group.

Write ${path}:
1. YAML frontmatter: title, topic, model: opus, id_family: ${families.join(', ')}, consolidates (the file list), date: ${DATE}.
2. "## Verdict" — 5-15 lines: the position this program takes, stated as DECISIONS, not as a survey. Where sub-researchers disagreed, decide and say why. Name the flake shape each decision binds (app flake / library or framework flake / module flake / generated flake / template) when it differs.
3. "## The ruleset" — merged, de-duplicated, numbered rules, one subsection per ID family this group owns (${families.join(', ')}). Each entry: ID (<FAMILY>-nn, e.g. NIX-FLK-01), the rule as an imperative sentence, rationale (one line — the failure it prevents), verification (exact nix command or eval expression, statix/deadnix/nixfmt/flake-checker invocation, jq over flake.lock, or grep with a directory operand; or a named reading heuristic), whether the verification was watched going red on a planted fixture (cite the dive's Verification runs), severity (MUST / SHOULD / CONSIDER), and the Nix / nixpkgs version floor and implementation it assumes if any. A MUST needs either a normative or measured source AND a verification that was run, or an explicit statement why it can only be a reading heuristic. Drop rules that are generic model common knowledge and would not change behaviour; keep the ones an agent gets wrong without being told. Smallest set with the highest yield. Group rows by the check that catches them.
4. "## Applied to the exemplars and the future consumers" — which rules the strict exemplars already satisfy, which prominent exemplars violate (repo@sha12:path:line from the audits or sub-artifacts), and which are new commitments for the fleet's flakes and the ocx generated flake.
5. "## AI-agent failure modes" — merged, ranked by how often it bites, each with the mechanical check.
6. "## Open questions" — what needs an owner decision (with the default the program will apply), and which subarea deserves ANOTHER research round (name the subarea and the question).
7. "## Sub-artifacts" — relative markdown links to each nix-${group}/<file>.md with a one-line description.
8. "## Key sources" — the 10-15 best URLs across all sub-artifacts.

Merge rules: no claim without a citation that traces to a sub-artifact or a URL; no duplicated rules; prefer the more specific formulation; when two sub-artifacts conflict, state the conflict and resolve it with a reason. A consolidation with no resolved conflict and no "violated" row is a survey wearing a verdict's clothes — do not produce one.`

  return agent(
    `Model rationale: opus — synthesis across conflicting sources plus normative decisions that later become enforced rules.

${CONTEXT}

TOPIC: ${label} (family ${family})

${task}

You may re-run a sub-artifact's recorded verification with ${RUN} to settle a conflict. Do not modify any file other than ${path}.

Return ONLY the structured receipt: path, rule IDs with one-line imperatives, conflicts resolved, subareas needing another round, and the MUST count.`,
    { label: (revise ? 'revise:' : 'consolidate:') + group, phase: 'Consolidate', model: 'opus', effort: 'high', schema: CONSOLIDATE_SCHEMA },
  )
}

// ---------------------------------------------------------------- Run
const groups = {}
for (const item of SELECTION) (groups[item.group] = groups[item.group] || []).push(item)
const entries = Object.entries(groups)
log('Wave ' + WAVE + ': ' + SELECTION.length + ' dives across ' + entries.length + ' groups (' + entries.map(([g, i]) => g + 'x' + i.length).join(', ') + '); revising: ' + (entries.filter(([g]) => EXISTING.has(g)).map(([g]) => g).join(', ') || 'none'))

const results = await pipeline(
  entries,
  ([group, items]) => parallel(items.map(item => () => dive(item).then(r => ({ slug: item.slug, ...(r || {}), ok: !!r })))),
  (dives, [group, items]) => {
    const ok = dives.filter(Boolean).filter(d => d.ok)
    if (!ok.length) { log('SKIP consolidate:' + group + ' — every dive dropped'); return { group, dives, consolidation: null } }
    if (ok.length < items.length) log('consolidate:' + group + ' proceeding with ' + ok.length + '/' + items.length + ' dives')
    return consolidate(group, items).then(c => ({ group, dives, consolidation: c }))
  },
)

const out = results.filter(Boolean)
const surprises = out.flatMap(r => (r.dives || []).filter(Boolean).flatMap(d => (d.surprises || []).map(s => r.group + '/' + d.slug + ': ' + s)))
const another = out.flatMap(r => ((r.consolidation && r.consolidation.needs_another_round) || []).map(s => r.group + ': ' + s))
const musts = out.reduce((n, r) => n + ((r.consolidation && r.consolidation.must_count) || 0), 0)
log('Wave ' + WAVE + ' done: ' + out.length + '/' + entries.length + ' groups consolidated · ' + musts + ' MUST rules · ' + surprises.length + ' surprises · ' + another.length + ' follow-ups')
return { wave: WAVE, groups: out, surprises, needs_another_round: another, must_count: musts }
